  // Spec: Subtotal equals the sum of line totals
  await expect(page.getByTestId("cart-subtotal")).toHaveText("$54.00");
  // Spec: Total equals subtotal minus discount
  await expect(page.getByTestId("cart-total")).toHaveText("$54.00");
